// === Tab: mySketch ===
/******************
Flow-field study for Nano Banana 2
https://www.nano-banana2.online/
******************/

let particles = [];
let palette = [];
let modeIndex = 0;
let lastModeChange = 0;
let modeDuration = 4200;
let xScale, yScale, centerX, centerY;

function setup() {
  createCanvas(windowWidth, windowHeight);
  textAlign(CENTER, CENTER);
  xScale = width / 22;
  yScale = (height / 22) * (width / height);
  centerX = width / 2;
  centerY = height / 2;
  palette = [
    color('#1a0633'),
    color('#6d1b7b'),
    color('#f6c445'),
    color('#ffd86b'),
    color('#ff8c42')
  ];
  background('#120224');
}

function draw() {
  if (particles.length === 0) {
    background('#120224');
    noStroke();
    fill(248, 230, 160, 220);
    textSize(max(width, height) * 0.035);
    text('Press and drag to release banana signals', centerX, centerY);
    textSize(max(width, height) * 0.018);
    fill(255, 205, 90, 180);
    text('A Nano Banana inspired flow field study', centerX, centerY + 42);
    return;
  }

  noStroke();
  fill(18, 2, 36, 18);
  rect(0, 0, width, height);

  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    emitParticles((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 16);
  }

  let now = millis();
  if (now - lastModeChange > modeDuration) {
    lastModeChange = now;
    modeIndex = (modeIndex + 1) % 6;
  }

  let stepSize = deltaTime * 0.0018;
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    let vx = slopeX(p.fx, p.fy, modeIndex);
    let vy = slopeY(p.fx, p.fy, modeIndex);

    p.fx += p.dir * vx * stepSize;
    p.fy += p.dir * vy * stepSize;

    let sx = plotX(p.fx);
    let sy = plotY(p.fy);

    stroke(p.color);
    strokeWeight(p.weight);
    line(sx, sy, p.px, p.py);

    p.px = sx;
    p.py = sy;
    p.life--;

    if (sx < -180 || sy < -180 || sx > width + 180 || sy > height + 180 || p.life <= 0) {
      particles.splice(i, 1);
    }
  }
}

function mousePressed() {
  emitParticles((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 22);
}

function emitParticles(mx, my, count) {
  for (let i = 0; i < count; i++) {
    var sx = mx + random(-110, 110);
    var sy = my + random(-110, 110);
    particles.push({
      fx: fieldX(sx),
      fy: fieldY(sy),
      px: sx,
      py: sy,
      weight: random(1.1, 4.2),
      life: floor(random(80, 180)),
      color: color(random(['#f6c445', '#ffd86b', '#ff8c42', '#8c52ff', '#ff5ea8'])),
      dir: random() > 0.5 ? 1 : -1
    });
  }
}

function slopeY(x, y, mode) {
  switch (mode) {
    case 0: return sin(x * 1.4) * cos(y * 0.4);
    case 1: return cos(x * y * 0.22);
    case 2: return -sin(x * 0.2) * 2.2;
    case 3: return (x - x * x * x) * 0.015;
    case 4: return cos(x) * y * 0.35;
    case 5: return -y - sin(1.2 * x) + 0.8;
  }
}

function slopeX(x, y, mode) {
  switch (mode) {
    case 0: return cos(y * 1.3) * sin(x * 0.3);
    case 1: return 1;
    case 2: return sin(y * 0.2) * 2.2;
    case 3: return y / 2.8;
    case 4: return sin(y * 1.1) * x * 0.18;
    case 5: return -1.2 * y;
  }
}

function fieldX(x) {
  return (x - centerX) / xScale;
}

function fieldY(y) {
  return (y - centerY) / yScale;
}

function plotX(x) {
  return x * xScale + centerX;
}

function plotY(y) {
  return y * yScale + centerY;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  xScale = width / 22;
  yScale = (height / 22) * (width / height);
  centerX = width / 2;
  centerY = height / 2;
  background('#120224');
  particles = [];
}

